use genex::prelude::*;

/// The barrel's end in the gun's own space (metres): the one place the flash, the light and the smoke start.
const MUZZLE: Vec3 = Vec3::new(0.0, 0.035, -0.19);
const FLASH_TICKS: u64 = 3;

fn draw_muzzle(w: &super::World, frame: &mut Frame, gun: Transform) {
    let since = w.tick.saturating_sub(w.fired_tick);
    if since >= FLASH_TICKS { return; }
    // The same transform the gun was drawn with: the flash cannot be left behind in the world.
    let at = gun.translation + gun.rotation * MUZZLE;
    frame.tag("muzzle");
    frame.sphere_with(at, 0.03, &Material::emissive(Color::rgb(255, 196, 120), 30.0));
    frame.point_light(at, 4.0, Color::rgb(255, 180, 110), 6.0);
}

/// The demo the check reads: one shot, then how far the flash sat from the barrel's end.
fn fire_demo(d: &mut DemoDriver<super::World>) -> Value {
    d.sim_mut().world.fire_requested = true;
    d.advance_ms(17);
    let w = &d.sim().world;
    json!({ "muzzleFromBarrel": w.last_flash_at.distance(w.last_barrel_end) })
}
